// === Tab: mySketch ===
let texture
function preload(){
	texture = loadImage("https://openprocessing.org/sketch/2500803/files/paper20240106.jpg")
}

async function setup() {
	const canvaSize = max(max(windowWidth, windowHeight), 700)
	createCanvas(canvaSize, canvaSize);
	background(255);

	const pAng = 0.577

	const segment = 150
	for(let i=0;i<segment;i++){
		const y = map(i,segment,0,30,height-30)

		for(let j=0;j<segment;j++){
			const x = map(j,0,segment,30,width-30)

			const xProjection = 0.503*x  + 0.501*y
			const yProjection = height*0.5 + 0.5*pAng*x  - 0.5*pAng*y

			const n1 = noise(x*0.1, y*0.1)
			const n2 = noise(x*0.007+100, y*0.007)
			const n3 = noise(x*0.001+500, y*0.001)

			if(n2>0.5){

				const dustColor1 = color("#D3CCC1")
				const dustColor2 = color("#6F6759")
				// noStroke()

				const dustColor = lerpColor(dustColor1,dustColor2,(n2-0.5)*2)
				stroke(dustColor)
				// stroke(0)
				fill(255)
				rect(xProjection, yProjection -n1*5-(n2-0.5)*100, 3, (n2-0.5)*800 +n1*5-(n2-0.5)*150)


				const grassColor1 = color("#A5AC98")
				const grassColor2 = color("#455242")
				const grassColor = lerpColor(grassColor1,grassColor2,(n2-0.5)*2)
				stroke(grassColor)
				fill(255,50)
				rect(xProjection, yProjection + n1*5-(n2-0.5)*150, 3, -5*n3-2)
			}

		}
		await sleep(10)
	}

	push()
	tint(255,50)
	blendMode(MULTIPLY)
	image(texture,0,0)
	pop()
}

